mapper.select:
SELECT id AS couponTemplateId, name AS couponName, logo_url AS couponLogo, type AS couponType, discount_rate, discount_amount, issued_quantity, min_spend_amount, max_deductible_amount, receive_limit_per_user
FROM coupon_templates WHERE coupon_status = 'ACTIVE' AND is_deleted = 0 AND is_enable = 1 AND merchant_id = #{merchantId}
ORDER BY sort_order DESC
